import sys; sys.path.insert(0, "source")
from pyscf import lib, dft; lib.num_threads(1)
from task002_benchmark import build_molecule, load_validation_study_systems

systems = load_validation_study_systems("fragment_epsilon")
for s in systems:
    mol = build_molecule(s.atom_spec)
    if mol.spin == 0:
        continue
    res = {}
    for guess in ("minao", "atom", "hcore"):
        try:
            mf = dft.UKS(mol); mf.xc="PBE"; mf.grids.level=1
            mf.conv_tol=1e-9; mf.conv_tol_grad=1e-6
            mf.init_guess = guess
            mf.kernel()
            res[guess] = (mf.converged, mf.e_tot)
        except Exception as e:
            res[guess] = ("err", str(e)[:40])
    print(s.label, {k:(v[0], None if v[0]=="err" else round(v[1],8)) for k,v in res.items()})
EOF

